// Collect this function's extra (vararg) arguments into an array of character handles
if (vargc > 0)
{
	local lockedCharas = array(vargc);
	for (local n = 0; n < vargc; ++n)
	{
		lockedCharas[n] = vargv[n];
	}
	// Lock talk interaction for all of them while this NPC is being talked to
	CMND_SET_TALK_LOCK_CHARA(lockedCharas);
}
